    """返回 {id: (err, params) 或 None}，顺序按 ids。任何一颗超时不影响后面的。"""
    out = {}
    with self._io:
        self._send(BROADCAST, SYNC_READ, bytes([addr, n]) + bytes(ids))
        for sid in ids:
